Чтобы написать скрипт контроллера от первого лица в GDScript и применить его к узлу KinematicBody в Godot Engine 3.x, следуйте этим шагам:

1. Создайте новый проект в Godot Engine 3.x и добавьте KinematicBody в сцену.
2. Создайте новый скрипт, назовите его "player_controller.gd" и скопируйте в него следующий код:

```gdscript
extends KinematicBody

export var speed := 6.0
export var gravity := -24.0
export var jump_speed := 10.0

var velocity := Vector3.ZERO

func _ready():
    $CharacterController.disabled = true

func _physics_process(delta):
    var direction := Vector3.ZERO

    if Input.is_action_pressed("move_forward"):
        direction += transform.basis.x
    if Input.is_action_pressed("move_backward"):
        direction -= transform.basis.x
    if Input.is_action_pressed("move_right"):
        direction += transform.basis.z
    if Input.is_action_pressed("move_left"):
        direction -= transform.basis.z

    if direction:
        direction = direction.normalized()

    var desired_velocity := speed * direction

    velocity.y += gravity * delta
    velocity.x = lerp(velocity.x, desired_velocity.x, 0.2)
    move_and_slide(velocity, Vector3.UP)

func _input(event):
    if event.is_action_pressed("jump"):
        if is_on_floor():
            velocity.y = jump_speed

func _on_character_controller_no_floor_detector_body_exited(body):
    if body.is_in_group("enemies"):
        queue_free()
```

3. В проекте Godot Engine 3.x, откройте сцену, где вы хотите использовать скрипт контроллера от первого лица, и в объекте KinematicBody, установите файл скрипта на "player_controller.gd".
4. Создайте группу "enemies" в проекте Godot Engine 3.x, если вы хотите, чтобы игрок мог упасть на врагов и умереть.

